missing = []
for fr, en in T:
    if fr not in s:
        missing.append(fr[:90])
    s = s.replace(fr, en)
if missing:
    print('Textes introuvables (index.html a changé ?) :'); [print(' -', m) for m in missing]; sys.exit(1)
(ROOT / 'en.html').write_text(s, encoding='utf-8')
print('en.html écrit,', len(T), 'remplacements')
